sys_script_client.script:
function onSubmit() {

	var course = g_form.getValue('course');
	var date = g_form.getValue('date').split("/");
	date = date[2] + "-" + date[1] + "-" + date[0];

	var ga = new GlideAjax('x_1593179_traini_0.TrainingUtils');
	ga.addParam('sysparm_name', 'validateSchedule');
	ga.addParam('sysparm_course', course.toString());
	ga.addParam('sysparm_date', date.toString());

	ga.getXMLAnswer(function(response) {
		alert(response);
		if (response === 'true') {
			g_form.addErrorMessage('There is already a schedule for this Course and Date');
			g_form.submit(false);
		} else {
			g_form.submit(true);
		}
	});

	return false;

}
